/**
 * Service Service - Reactive service data management
 * Handles loading and managing a single service's data, loading state, and errors.
 */
import { defineService, implementService } from '@wix/services-definitions';
import { SignalsServiceDefinition, } from '@wix/services-definitions/core-services/signals';
import { ServiceType, RateType, } from '@wix/auto_sdk_bookings_services';
import { getServiceById, getServiceBySlug, } from '../../api/query-services/index.js';
import { BookingServiceDefinition } from '../booking/booking.js';
import { convertToMoneyData } from '../../utils/money.js';
/**
 * Booking app ID constant
 */
import { BOOKING_APP_ID } from '../constants.js';
/**
 * Service definition for the Service service.
 * This defines the contract that the ServiceService must implement.
 *
 * @constant
 */
export const ServiceServiceDefinition = defineService('service');
/**
 * Implementation of the Service service that manages reactive service data.
 * This service provides signals for service data, loading state, and error handling,
 * along with methods to dynamically load services.
 *
 * @example
 * ```tsx
 * import { ServiceService, ServiceServiceDefinition } from '@wix/bookings/services';
 * import { useService } from '@wix/services-manager-react';
 *
 * function ServiceComponent({ serviceConfig }) {
 *   return (
 *     <ServiceProvider services={createServicesMap([
 *       [ServiceServiceDefinition, ServiceService.withConfig(serviceConfig)]
 *     ])}>
 *       <ServiceDisplay />
 *     </ServiceProvider>
 *   );
 * }
 *
 * function ServiceDisplay() {
 *   const serviceService = useService(ServiceServiceDefinition);
 *   const service = serviceService.serviceSignal.get();
 *   const isLoading = serviceService.isLoadingSignal.get();
 *   const error = serviceService.errorSignal.get();
 *
 *   if (isLoading) return <div>Loading...</div>;
 *   if (error) return <div>Error: {error}</div>;
 *
 *   return <h1>{service.name}</h1>;
 * }
 * ```
 */
export const ServiceService = implementService.withConfig()(ServiceServiceDefinition, ({ getService, config }) => {
    const signalsService = getService(SignalsServiceDefinition);
    // Determine if we're in "from booking signal" mode (no service config provided)
    const noExplicitService = !config.service && !config.serviceId && !config.serviceSlug;
    // Try to get BookingService (optional dependency for showcase mode)
    let bookingService = null;
    try {
        bookingService = getService(BookingServiceDefinition);
    }
    catch {
        // BookingService not available - showcase mode
        bookingService = null;
    }
    // In "from booking signal" mode, BookingService must be available
    if (noExplicitService && !bookingService) {
        throw new Error('Service.Root requires either a service config (service, serviceId, or serviceSlug) or BookingService to be available');
    }
    // Initialize service signal
    // In "from booking signal" mode, use a computed signal that reads from BookingService
    let serviceSignal;
    if (noExplicitService && bookingService) {
        // Create a computed signal that reads from BookingService's first selected service
        const computedServiceSignal = signalsService.computed(() => {
            const selections = bookingService.serviceSelections.get();
            return selections[0]?.service || null;
        });
        // Wrap computed signal as a Signal (read-only in practice for this mode)
        serviceSignal = computedServiceSignal;
    }
    else {
        // Standard mode: use provided service or empty object
        const initialService = config.service || {};
        serviceSignal = signalsService.signal(initialService);
    }
    const isLoadingSignal = signalsService.signal(!config.service && (!!config.serviceId || !!config.serviceSlug));
    const errorSignal = signalsService.signal(null);
    // Default appId to BOOKING_APP_ID if not provided
    const appId = config.appId ?? BOOKING_APP_ID;
    // bookable signal - true if appId equals booking app ID
    const bookableSignal = signalsService.computed(() => {
        return appId === BOOKING_APP_ID;
    });
    // selected signal - true if current service is in BookingService preferences
    const selectedSignal = signalsService.computed(() => {
        if (!bookingService)
            return false;
        const currentService = serviceSignal.get();
        if (!currentService._id)
            return false;
        const serviceSelections = bookingService.serviceSelections.get();
        return serviceSelections.some(({ service }) => service._id === currentService._id);
    });
    // requiresAvailability signal - true for APPOINTMENT and CLASS types
    const requiresAvailabilitySignal = signalsService.computed(() => {
        const currentService = serviceSignal.get();
        const serviceType = currentService.type;
        return (serviceType === ServiceType.APPOINTMENT ||
            serviceType === ServiceType.CLASS);
    });
    // paymentData signal - computed payment data from service
    const paymentDataSignal = signalsService.computed(() => {
        const service = serviceSignal.get();
        const payment = service.payment;
        const rateType = payment?.rateType;
        // Initialize all price-related values
        let money = null;
        let minPrice = null;
        let maxPrice = null;
        let priceDescription = null;
        // Extract pricing based on rate type
        if (payment) {
            switch (rateType) {
                case RateType.FIXED:
                    // FIXED: Use payment.fixed.price
                    money = convertToMoneyData(payment.fixed?.price);
                    break;
                case RateType.VARIED:
                    // VARIED: Use defaultPrice as money, plus min/max for range
                    money = convertToMoneyData(payment.varied?.defaultPrice);
                    minPrice = convertToMoneyData(payment.varied?.minPrice);
                    maxPrice = convertToMoneyData(payment.varied?.maxPrice);
                    break;
                case RateType.CUSTOM:
                    // CUSTOM: Use description text (no numeric price)
                    priceDescription = payment.custom?.description || null;
                    break;
                case RateType.NO_FEE:
                    // NO_FEE: Free service (amount = 0)
                    money = { amount: 0, currency: 'USD' };
                    break;
                default:
                    // UNKNOWN_RATE_TYPE or undefined - leave all null
                    break;
            }
        }
        // Derive service capabilities
        const hasAddOns = (service.addOnGroups?.length ?? 0) > 0;
        const hasPricingPlans = (payment?.pricingPlanIds?.length ?? 0) > 0;
        return {
            servicePayment: payment,
            rateType,
            money,
            minPrice,
            maxPrice,
            priceDescription,
            hasAddOns,
            hasPricingPlans,
        };
    });
    const loadServiceById = async (id) => {
        isLoadingSignal.set(true);
        errorSignal.set(null);
        const serviceResponse = await getServiceById(id, appId);
        if (!serviceResponse.service) {
            errorSignal.set('Service not found');
            isLoadingSignal.set(false);
        }
        else {
            serviceSignal.set(serviceResponse.service);
            errorSignal.set(null);
            isLoadingSignal.set(false);
        }
    };
    const loadServiceBySlug = async (slug) => {
        isLoadingSignal.set(true);
        errorSignal.set(null);
        const serviceResponse = await getServiceBySlug(slug, appId);
        if (!serviceResponse.service) {
            errorSignal.set('Service not found');
            isLoadingSignal.set(false);
        }
        else {
            serviceSignal.set(serviceResponse.service);
            errorSignal.set(null);
            isLoadingSignal.set(false);
        }
    };
    // Auto-load if serviceId or serviceSlug is provided but no service data
    // Priority: service > serviceSlug > serviceId
    if (!config.service) {
        if (config.serviceSlug) {
            loadServiceBySlug(config.serviceSlug);
        }
        else if (config.serviceId) {
            loadServiceById(config.serviceId);
        }
    }
    // Action methods for booking - only work when bookable is true
    const actions = {
        select: () => {
            if (!bookableSignal.get() || !bookingService)
                return;
            const currentService = serviceSignal.get();
            bookingService.actions.setItem({
                service: currentService,
                resources: [],
            });
        },
        add: () => {
            if (!bookableSignal.get() || !bookingService)
                return;
            const currentService = serviceSignal.get();
            bookingService.actions.addItem({
                service: currentService,
                resources: [],
            });
        },
        remove: () => {
            if (!bookableSignal.get() || !bookingService)
                return;
            const currentService = serviceSignal.get();
            // Remove all instances of this service (by serviceId)
            const serviceSelections = bookingService.serviceSelections.get();
            const instancesToRemove = serviceSelections
                .filter((s) => s.service._id === currentService._id)
                .map((s) => s.instanceId);
            instancesToRemove.forEach((instanceId) => {
                bookingService.actions.removeItem(instanceId);
            });
        },
    };
    return {
        serviceSignal,
        isLoadingSignal,
        errorSignal,
        loadServiceById,
        bookableSignal,
        selectedSignal,
        requiresAvailabilitySignal,
        paymentDataSignal,
        actions,
    };
});
/**
 * Load service configuration for Server-Side Rendering (SSR).
 * This function is designed to be called during the build or server-side rendering phase
 * to pre-fetch service data before the React components are hydrated on the client.
 *
 * @param params - Either `{ slug: string, appId?: string }` or `{ serviceId: string, appId?: string }`
 * @returns A promise that resolves to either a success result with the config or a notFound result
 *
 * @example
 * ```ts
 * // In an Astro page or API route
 * import { loadServiceServiceInitialData } from '@wix/headless-bookings/services';
 *
 * // Load by slug
 * const serviceResult = await loadServiceServiceInitialData({ slug: 'group-trainings' });
 *
 * // Load by serviceId
 * const serviceResult = await loadServiceServiceInitialData({ serviceId: 'service-id-123' });
 *
 * if (serviceResult.type === 'notFound') {
 *   return Astro.redirect('/404');
 * }
 *
 * const serviceConfig = serviceResult.config;
 * ```
 */
export async function loadServiceServiceInitialData(params) {
    try {
        // Default appId to BOOKING_APP_ID if not provided
        const finalAppId = params.appId ?? BOOKING_APP_ID;
        let serviceResponse;
        if ('slug' in params) {
            serviceResponse = await getServiceBySlug(params.slug, finalAppId);
        }
        else {
            serviceResponse = await getServiceById(params.serviceId, finalAppId);
        }
        if (!serviceResponse.service) {
            return { type: 'notFound' };
        }
        return {
            type: 'success',
            config: {
                service: serviceResponse.service,
                appId: finalAppId,
            },
        };
    }
    catch (error) {
        const identifier = 'slug' in params ? `slug "${params.slug}"` : `id "${params.serviceId}"`;
        console.error(`Failed to load service for ${identifier}:`, error);
        return { type: 'notFound' };
    }
}
